\subsection{Environments and Tasks} \begin{figure*}[t]
\vskip 0.2in
\begin{center}
\centerline{\includegraphics[width=\linewidth]{figures/env.pdf}}
\caption{The environments used in our experiments: Walker Walk, Walker Run, Cheetah Run, Finger Spin, Hopper Hop, and Car Racing, where the first five replace backgrounds with natural videos except for Car Racing.}
\label{fig:env}
