\section{Slowly Updating Linear Bandits} \newcommand{\explore}{\mathrm{EXPLORE}}
\begin{algorithm} \caption{Slow Update Linear UCB}
\label{alg:slow-upd-ucb}
\SetKwInput{kwInit}{Initialize}
\SetKwInput{kwParam}{Parameters}
\kwParam{policy update rate $c$}
\kwInit{Gram matrix $V_0 \leftarrow \lambda I$ and $y_0 \leftarrow 0$}
\kwInit{previous update index $\tau = 0$ and update index $u=1$}

\For{each round $t = 1, \dots, T$}
{
\If{\upt}
{
Observe decision set $\mathcal{A}_t$.\\
Observe regularized $\Vtil_t \leftarrow \V_t + \mH_t$ and perturbed $\ytil = \cM_y(u)$\\
Compute regressor $\thetahat_t = \Vtil^{-1}_t \ytil_t$\\
Construct confidence set $C_t = \{ \theta: \| \theta - \thetatil_t \|_{\Vtil_t} \leq \sqrt{\beta_t} \}$ 

}
Pick action $\avec_t = \arg \max_{\avec \in \mathcal{A}_t} \langle \thetahat_\tau, \avec \rangle + \beta_\tau \| \avec \|_{\Vtil_\tau^{-1}}$\\
Play $\avec_t$ and observe reward $r_t$\\
Feed $\avec_t \avec_t^\top$ to $\cM_V$\\
Update $\Vtil_t \leftarrow \cM(t)$
}
\end{algorithm}
\begin{assumption}
\label{asmp: bounded-mean-reward}
We assume 
\begin{itemize}
    \item Bounded mean reward $|\langle \thetabf^*, \avec \rangle | \leq B$ with $B \geq 1$
\end{itemize}
\end{assumption}
\begin{assumption} 
\label{asmp: bounded-action}
For all rounds $t = 1, \dots, n$ and actions $\avec \in \mathcal{A}_t$, we assume
\begin{itemize}
    \item Bounded action set: $\|\avec \|_2 \leq L$
\end{itemize}
\end{assumption}
\begin{assumption}
\label{asmp: bounded-reward}
We assume 
\begin{itemize}
    \item Bounded reward vector $\|\thetabf^* \|_2 \leq S$
\end{itemize}
\end{assumption}
\begin{assumption} For all rounds $t = 1, \dots, n$, we assume
\begin{itemize} 
    \item The added noise by the binary mechanism $\mH_t$ is positive semidefinite {\color{red}this is no longer needed in our algorithm? }
\end{itemize}
\end{assumption}
\begin{assumption}
\label{asmp:reward-formula}
For all rounds $t = 1, \dots, n$, we assume:
\begin{itemize}
    \item $r_t = \langle \thetabf^*, \avec_t \rangle + \eta_t$ where $\eta_t$ is $\sigma^2-$conditionally subgaussian on previous actions and rewards
\end{itemize}
\end{assumption}
\begin{assumption} For all rounds $t = 1, \dots, n$, we assume the
\begin{itemize}  
    \item $\|\mH_t\| \leq \rho_{\max}$, $\|\mH_t^{-1}\| \leq 1/\rho_{\min}$, $\|\h_t\|_{\mH_t^{-1}}\leq \gamma$ 
\end{itemize}
\end{assumption}
\begin{proposition}
\label{prop:calc-beta}
Suppose Assumptions $\ref{asmp: bounded-reward}$ to $\ref{asmp:reward-formula}$ holds, and let $\rho_{\max}, \rho_{\min},$ and $\gamma$ be $(\alpha/2n)$-accurate for some $\alpha \in (0,1)$, and horizon $n$. Then $(\beta_t)_{t=1}^n$ is a $(\alpha, n)-$accurate where 
\begin{align*}
    \beta_t &= \sigma\sqrt{2\log(2/\alpha) + \log(\det(\V_t)) - d\log(\rho_{\min})} + S\sqrt{\rho_{\max}} + \gamma\\
    &\leq \sigma\sqrt{2\log(2/\alpha) + d\log\left( \frac{\rho_{\max}}{\rho_{\min}} + \frac{tL^2}{d \rho_{\min}}\right)} + S\sqrt{\rho_{\max}} + \gamma \tag{if Assumption \ref{asmp: bounded-action} also holds}
\end{align*}
\end{proposition}
\begin{theorem} (Regret of Algorithm \ref{alg:slow-upd-ucb})
Suppose Assumptions $\ref{asmp: bounded-mean-reward}$ to $\ref{asmp:reward-formula}$ hold and the $\beta_t$ are given by Proposition $\ref{prop:calc-beta}$. Then with probability at least $1 - \alpha$, the pseudo-regret of Algorithm $\ref{alg:slow-upd-ucb}$ is bounded by 
\begin{equation}
    \hat{R_n} \leq B\sqrt{8n}\left[ \sigma\left( 2\log\left( \frac{2}{\alpha}
    \right) + d\log \left(\frac{\rho_{\max}}{\rho_{\min}}\right)\right) \right]
\end{equation}
\end{theorem}

