\subsection{Preliminaries and notation} We provide the organization for prior works in \cref{appendix : prior work}. 
Here, we review standard definitions and set up the notation.


\paragraph{Monotone and set-valued operators.} 
We follow the standard definitions of \citet{BauschkeCombettes2017_convex, RyuYin2022_largescale}.
For the underlying space, consider $\reals^n$ with standard inner product $\inner{\cdot}{\cdot}$ and norm $\norm{\cdot}$. 
Define domain of $\opA$ as $\dom \opA = \set{ x \in \RR^n \mid \opA x \ne \emptyset }$. 
We say $\opA$ is an operator on $\reals^n$ and write $\opA \colon \reals^n \rightrightarrows \reals^n$ if $\opA$ maps a point in $\reals^n$ to a subset of $\reals^n$. 
We say $\opA\colon\mathbb{R}^n\rightrightarrows\mathbb{R}^n$ is monotone if
\begin{align*}
    \langle \opA x-\opA y,x-y\rangle \ge 0,\qquad\forall x,y\in \mathbb{R}^n,    
\end{align*}
where the notation means that $\langle u-v,x-y\rangle\ge 0$ for all $u\in \opA x$ and $v\in \opA y$.
For $\mu \in (0,\infty)$, say $\opA \colon\mathbb{R}^n\rightrightarrows\mathbb{R}^n$ is $\mu$-strongly monotone if
\begin{equation*}
    \langle \opA x-\opA y,x-y\rangle \geq \mu\|x-y\|^2,\qquad\forall x,y\in \mathbb{R}^n.
\end{equation*}
Write $\gra \opA = \set{(x, u) \mid u \in \opA x}$ for the graph of $\opA$.
An operator $\opA$ is maximally monotone if there is no other monotone $\opB$ such that $\gra\opA \subset \gra\opB$ properly, and is maximally $\mu$-strongly monotone if there is no other $\mu$-strongly monotone  $\opB$ such that $\gra\opA \subset \gra\opB$ properly.

For $L\in (0,\infty)$, single-valued operator $\opT \colon\mathbb{R}^n\to\mathbb{R}^n$ is $L$-Lipschitz if
\begin{equation*}
    \|\opT x-\opT y\|\le L\|x-y\|,\qquad\forall x,y\in \mathbb{R}^n.
\end{equation*}
Write $\opJ_\opA = (\opI + \opA)^{-1}$ for the resolvent of $\opA$, while $\opI\colon\mathbb{R}^n\rightarrow\mathbb{R}^n$ is the identity operator. 
When $\opA$ is maximally monotone, it is well known that $\opJ_\opA$ is single-valued with $\dom\opJ_\opA=\reals^n$. 

We say $x_\star \in \reals^n$ is a zero of $\opA$ if $0 \in \opA x_\star$. We say $y_\star$ is a fixed-point of $\opT$ if $\opT y_\star = y_\star$. Write $\zer\opA$ for the set of all zeros of $\opA$ and $\fix\opT$ for the set of all fixed-points of $\opT$. 


\paragraph{Monotonicity with continuous curves.}
We say an operator is differentiable if it is single-valued, continuous, and differentiable as a function. 
If a differentiable operator $\opA$ is monotone and $\Z\colon[0,\infty)\to\OurSpace$ is a differentiable curve, then taking limit $h\to0$ of
\begin{align*}
    \frac{1}{h^2}\inner{\A(\Z(t+h))-\A(\Z(t))}{\Z(t+h)-\Z(t)} \ge 0
\end{align*}
leads to
\begin{equation}    \label{eq:continuous monotone inequality}
    \inner{ \frac{d}{dt} \A(\Z(t)) }{\dot{\Z}(t)} \ge 0 . 
\end{equation}
Similarly if $\opA$ is furthermore $\mu$-strongly monotone, then
\begin{equation} \label{eq:continuous strongly monotone inequality}
    \inner{ \frac{d}{dt} \A(\Z(t)) }{\dot{\Z}(t)} \ge \mu \norm{\dot{\Z}(t)}^2 .
\end{equation}

