\subsection{Equivalence of \SSO/ and SGD in Target Space} \label{app:smd-surrogate}
\restatesmdsurrogate*
\begin{proof}
Since $\ell$ is separable, if $i_t$ is the coordinate sampled from $z$, we can rewrite the target-space update as follows: 
\begin{align*}
\fth^{i_t} & = \ft^{i_t} - \etat \frac{\partial \ell_{i_t}(\ft)}{\partial z^{i_t}} \, \, \, \nonumber \\
\fth^j & = \ft^j \, \, \, \textrm{ when } j \neq i_t\nonumber \; .
\end{align*}
Putting the above update in the projection step we have, 
\begin{align*}
\tftt &= \argmin_{\z \in \cZ} \frac{1}{2}\{ \normsq{\fth^{i_t} - \z^{i_t}}\}\\
    &= \argmin_{\z \in \cZ} \frac{1}{2} \{ \normsq{\ft^{i_t} - \etat \frac{\partial \ell_{i_t}(\ft)}{\partial z^{i_t}} - \z^{i_t}} \}\\
    &= \argmin_{\z \in \cZ} \left\{ \left [ \frac{\partial \ell_{i_t}(\ft)}{\partial \z^{i_t}} \, [\z^{i_t} - \zt^{i_t}] + \frac{1}{2 \etat} \normsq{\z^{i_t} - \zt^{i_t}}  \right ] \right\} \tag{Due to separability of $\ell$} \\       
    \intertext{Since for all $\z \in \cZ$, $\z = f(\theta)$ and $\z^{i} = f_i(\theta)$ for all $i$. Hence $\tftt = f(\tthtt)$ such that,}
    \tthtt &= \argmin_{\theta \in \Theta} \left\{\frac{\partial \ell_{i_t}(\ft)}{\partial \z^{i_t}} \, [f_{i_t}(\theta) - f_{i_t}(\tht)] + \frac{1}{2 \etat} \normsq{f_{i_t}(\theta) - f_{i_t}(\tht)} \right\} = \argmin_{\theta \in \Theta} \tilde{g}^\z_t(\theta) 
\end{align*}
% Since $\tftt = f(\tthtt)$, for all $j$, $\tftt^{j} = f_{j}(\tthtt)$, and hence all coordinates of $\tftt$ have been updated (though not necessarily via a stochastic gradient update). 
\end{proof}

\begin{lemma}
\label{app:lemma:smdsurrogate2}
Consider the following updates:
\begin{align}
\bthtt &= \argmin_{\theta} \tilde{q}_t(\theta) \quad \text{;} \quad \bftt^{(1)} = f(\bthtt) \tag{$\SSO/$}  \\
\fth & = \ft - \petat \, \nabla_{z} \ell_{i_t}(\ft)  \tag{Target-space SGD} \, \text{;} \\
\bftt^{(2)} & = \argmin_{\z \in \cZ} \frac{1}{2} \indnormsq{\fth - \z}{2} 
\nonumber
\end{align}
$\SSO/$ and target space SGD result in the same iterate in each step i.e. if $z_t = f(\tht)$, then $\bftt := \bftt^{(1)} = \bftt^{(2)}$.
