    &= \argmin_{\z \in \cZ} \left\{ \left [ \frac{\partial \ell_{i_t}(\ft)}{\partial \z^{i_t}} \, [\z^{i_t} - \zt^{i_t}] + \frac{1}{2 \petat} \normsq{\z - \zt}  \right ] \right\} \tag{Due to separability of $\ell$} \\       
    \intertext{Since for all $\z \in \cZ$, $\z = f(\theta)$. Hence $\bar{\z}_{t+1} = f(\bthtt)$ such that,}
\bthtt &= \argmin_{\theta \in \Theta} \left\{\frac{\partial \ell_{i_t}(\ft)}{\partial \z^{i_t}} \, [f_{i_t}(\theta) - f_{i_t}(\tht)] + \frac{1}{2 \petat} \normsq{f(\theta) - f(\tht)} \right\} \\
    & = \argmin_{\theta \in \Theta} \tilde{q}_t(\theta) 
\end{align*}
\end{proof}

