\section{Proofs for Section~\ref{sec:infinite-horizon} (Infinite-horizon MDPs)}
\label{sec:appendix-infinite-horizon-MDP}
In this section, we first show the relationship between the path length of policies and the path length of occupancy measures. Next, we show the proofs of the reduction to switching-cost expert problem in Section~\ref{sec:reduction}. Then, we give the proofs of the dynamic regret of our algorithm in Section~\ref{sec:dynamic-infinite-horizon} and finally we present the proofs of the impossibility result for switching-cost expert problem in Section~\ref{sec:adaptive-infinite-horizon}.

\subsection{Path Length of Policies and Occupancy Measures} \label{sec:appendix-infinite-horizon-occupancy-measure}
We introduce the relationship between the path length of policies and the path length of occupancy measures as follows.

\begin{myLemma}
    \label{lem:infinite-horizon-2}
    For any occupancy measure sequence $q_1, \ldots, q_T$ induced by the policy sequence $\pi_1, \ldots, \pi_T$, it holds that
    \begin{equation*}
        \sum_{t=2}^T \norm{q^{\pi_t} - q^{\pi_{t-1}}}_1 \leq (\tau+2) \sum_{t=2}^T \norm{\pi_t - \pi_{t-1}}_{1, \infty}.
    \end{equation*}
\end{myLemma}
\begin{proof}
    Consider any two policies $\pi$ and $\pi'$ with occupancy measure $q^{\pi}$ and $q^{\pi'}$, let $d^{\pi}(x) \triangleq \sum_{x,a} q^{\pi}(x,a), d^{\pi'}(x) \triangleq \sum_{x,a} q^{\pi'}(x,a), \forall x \in X$, we have
    \begin{align*}
        \norm{q^\pi - q^{\pi^\prime}}_1 & = \sum_{x,a} \abs{q^\pi(x,a) - q^{\pi^\prime}(x,a)}                                                                                                \\
                                        & = \sum_{x,a} \abs{d^\pi(x) \pi(a|x) - d^{\pi^\prime}(x) \pi^\prime (a | x)}                                                                        \\
                                        & \leq \sum_{x,a} \abs{d^\pi(x) \pi(a|x) - d^\pi(x) \pi^\prime(a|x)} + \sum_{x,a} \abs{d^\pi(x) \pi^\prime(a|x) - d^{\pi^\prime}(x) \pi^\prime(a|x)} \\
                                        & = \sum_x d^\pi(x) \sum_a \abs{\pi(a|x) - \pi^\prime(a|x)} + \sum_x \abs{d^\pi(x) - d^\prime(x)} \sum_a \pi^{\prime}(a|x)                           \\
                                        & \leq \norm{\pi-\pi^\prime}_{1, \infty} + \norm{d^\pi - d^{\pi^\prime}}_1                                                                           \\
                                        & \leq (\tau+2) \norm{\pi - \pi^\prime}_{1, \infty},
    \end{align*}
    where the first inequality holds due to the triangle inequality and the last inequality holds due to Lemma \ref{lem:infinite-horizon-1}. We finish the proof by summing the inequality over $T$.
\end{proof}

