\subsubsection{Combining the results} Now we combine \Cref{lemma:upper_bound_for_loss}
and \Cref{lemma:lower_bound_for_f} to give an approximation inequality
that is true for all core shapes.

\begin{lemma}
\label{lemma:sandwich_loss}
For any $\tensor{X}\in\mathbb{R}^{I_1\times\cdots\times I_N}$
and any core shape $\mat{r} = (R_1, R_2, \dots, R_N) \in [I_1] \times [I_2] \times \dots \times [I_N]$, we have
\[
    \frac{1}{N} \cdot \SurrogateLoss(\tensor{X}, \mat{r})
    \le
    \Loss(\tensor{X}, \mat{r})
    \le
    \SurrogateLoss(\tensor{X}, \mat{r}),
\]
where $\SurrogateLoss(\tensor{X}, \mat{r})$ is defined in Equation~\Cref{eqn:surrogate_loss_def}.
\end{lemma}

\begin{proof}
Summing Equation~\Cref{eqn:error_lower_bound}
in the proof of~\Cref{lemma:lower_bound_for_f}
over all values of $n \in [N]$ gives
\begin{equation}
\label{eqn:sum_modewise_tail_errors}
    \sum_{n=1}^N
    \sum_{i_n = R_{n}+1}^{I_n} \parens*{\sigma_{i_n}^{(n)}}^2
    \le
    N \cdot \Loss(\tensor{X}, \mat{r})
    \implies
    \frac{1}{N} \cdot \SurrogateLoss(\tensor{X}, \mat{r})
    \le
    \Loss(\tensor{X}, \mat{r}).
\end{equation}
