\subsection{Proof of \Cref{lem:hosvd_packing_problem} }
\label{subsec:proxy_sandwhich}

\HosvdPackingProblem*

\begin{proof}
For any $n$, we have
\begin{align*}
    \sum_{i_n=1}^{I_n} \parens*{\sigma_{i_n}^{(n)}}^2
    =
