\begin{theorem} \begin{theorem}
  \label{diststrmthm}
  Suppose input $\beta\geq 1$.
  \diststrm produces a solution $S$ such that $|S|\leq|OPT|/\epsilon$ and
  \begin{align*}
    g(S)-c(S)\geq (1-1/\beta-\epsilon(1-1/\beta))g(OPT)-(\beta+1-\epsilon(1-1/\beta))c(OPT).
  \end{align*}
  In particular, if $\beta=1/\epsilon$,
  \begin{align*}
    %g(S)-c(S)\geq (1-2\epsilon+\epsilon^2)g(OPT)-(1/\epsilon+1-\epsilon + \epsilon^2)c(OPT).
    g(S)-c(S)\geq (1-\epsilon)^2g(OPT)-(1/\epsilon-\epsilon + \epsilon^2+1)c(OPT).
  \end{align*}
\end{theorem}

\begin{proof} \begin{proof}
  First, consider the case where at the end of \diststrm $|S|=|OPT|/\epsilon$.
  Then,
  \begin{align*}
    g(S)-c(S) &\overset{(a)}{\geq} g(S)-g(\emptyset)-\beta c(S)\\
    &\overset{(b)}{\geq} \sum_{i=1}^{|S|}\left(\Delta g(S_{i-1},s_i)-\beta c(s_i)\right)\\
    &\overset{(c)}{\geq} |S|\epsilon\tau/|OPT|\\
    &\overset{(d)}{=} \tau\\
    &\geq g(OPT)-c(OPT).
  \end{align*}
  where (a) is because $\beta\geq 1$ and $g(\emptyset)\geq 0$;
  (b) is by submodularity of $g$;
  (c) is by the condition of adding an element to $S$;
  and (d) is by the assumption that $|S|=|OPT|/\epsilon$.

  Next, consider the case where at the end of \diststrm $|S|<|OPT|/\epsilon$.
  Then see that
  \begin{align}
    \label{eqn1}
    g(OPT)-g(S)-\beta c(OPT) &\overset{(a)}{\leq} g(OPT\cup S)-g(S)-\beta c(OPT)\nonumber\\
    &\overset{(b)}{\leq} \sum_{o\in OPT}\left(\Delta g(S,o)-\beta c(o)\right)\nonumber\\
    &\overset{(c)}{<} \epsilon\tau
  \end{align}
  where (a) is due to the monotonicity of $g$;
  (b) is due to submodularity of $g$;
  and (c) is due to submodularity combined with the fact that any element of
  $OPT$ is either in $S$ or had been rejected.

  In addition,
  \begin{align}
    \label{eqn2}
    g(S) - \beta c(S) &\overset{(a)}{\geq} g(S)-g(\emptyset)-\beta c(S)\nonumber \\
    &\overset{(b)}{\geq} \sum_{i=1}^{|S|}\left(\Delta g(S_{i-1},s_i)-\beta c(s_i)\right)\nonumber \\
    &\overset{(c)}{\geq} |S|\epsilon\tau/|OPT|\nonumber\\
    &\geq 0
  \end{align}
  where (a) is because $g(\emptyset)\geq 0$;
  (b) is by submodularity of $g$;
  and (c) is by the condition to add elements to $S$.

  Finally, we have that
  \begin{align*}
    g(S)-c(S) &\overset{(a)}{\geq} (1-1/\beta)g(S)\\
    &\overset{(b)}{\geq} (1-1/\beta)\left(g(OPT)-\beta c(OPT)-\epsilon\tau\right)\\
    &= (1-1/\beta)g(OPT)-(\beta+1)c(OPT)-(1-1/\beta)\epsilon\tau\\
    &\overset{(c)}{\geq}(1-1/\beta-\epsilon(1-1/\beta))g(OPT)-(\beta+1-\epsilon(1-1/\beta))c(OPT)
  \end{align*}
  where (a) is by Inequality \ref{eqn2};
  and (b) is by Inequality \ref{eqn1};
  and (c) is because $g(OPT)-c(OPT)\geq\tau$.
\end{proof}

