\subsubsection{Balanced classes and binary classification} The following result follows directly by combining Lemmas \ref{lem:norms_w}, \ref{lem:norms_h}, \ref{lem:angles_w}, \ref{lem:angles_h} and \ref{lem:angles_wh}. 

\begin{corollary}[$k=2$ or $R=1$: \emph{\ref{SELI}}$\equiv$\emph{\ref{ETF}}]\label{cor:SELI_to_ETF}
Assume $k=2$ or $R=1$. The following hold.
\begin{align*}
&\|\w_1\|_2=\ldots=\|\w_k\|_2\quad\text{ and }\quad
\|\h_1\|_2=\ldots=\|\h_n\|_2\,,
\\
&\forall c\neq c'\in[k],~\Cos{\w_c}{\w_c'}=-1/(k-1)\quad\text{ and }\quad &\forall i\neq i'\in[n],~\Cos{\h_i}{\h_i'}=-1/(k-1)\,,
\\
&\forall c\in[k], i\,:\,y_i=c,~\Cos{\w_c}{\h_i}=1.
\end{align*}
Thus, the SELI geometry is same as the ETF geometry in balanced and in binary classification.
\end{corollary}

