\subsection{Using the good events to restrict the outliers of $a_{k, s} $.}

Denote the shifted version of average reward as
\begin{equation*}
    \overline{R}_{k, s}^* := \frac{\lambda_1 + \sum_{\ell = 1}^s R_{k, \ell}}{s + \lambda_2}
\end{equation*}
Specify some good events such that $A_{k, s} := \{ \overline{R}_{k, s}^* - \mu_k > - C_1 \Delta_k\}$ (or $A_{k, s} := \{ \overline{R}_{k, s}^* - \mu_k < C_2 \Delta_k\}$) with some $C_1, C_2 > 0$ determined later, and define
\begin{equation*}
    a_{k, s, 1} := \E \Big[ \big( N_{1, s} (\tau_k) \wedge T \big) 1 (A_{1, s}) \Big], \qquad a_{k, s, 2} := \E \Big[ \big( N_{1, s} (\tau_k) \wedge T \big) 1 (A_{1, s}^c) \Big],
\end{equation*}
with $s_{a, j} (T) := \min \{ s : a_{k, s, j} \leq T^{-1}\}$ (it is well-defined by the fact $\mu_1 > 0.5$). In this step, our target is to show that $\max_{j = 1, 2} s_{a, j} (T) \lesssim \log T$. Indeed, if we have proved this, then 
\begin{equation*}
    \begin{aligned}
        a_k & \leq M(\mu_1, \lambda_1, \lambda_2) \cdot \max_{j = 1, 2} s_{a, j} (T) + (T - \max_{j = 1, 2} s_{a, j} (T)) \cdot 2 T^{-1} \\
        & \lesssim 2 + M(\mu_1, \lambda_1, \lambda_2) \log T.
    \end{aligned}
\end{equation*}
As a result, it is sufficient to show that $\max_{j = 1, 2} s_{a, j} (T) \lesssim \log T$.

\subsubsection{Tackling $a_{k, s, 2} $}

The construction of $\overline{R}_{k, s}^*$ indicates the behave of $\overline{R}_{k, s}^*$ is quite similar to the true value $\overline{Y}_{k, s}$, so we study the probability of the bad event $A_{1, s}^c$ (using the first definition) with Hoeffding inequality
\begin{equation*}
    \begin{aligned}
        \pr (A_{1, s}^c) & = \pr \bigg\{ \sum_{i = 1}^s R_{1, i} \leq (\mu_1 - C_1 \Delta_k) (s + \lambda_2) - \lambda_1 \bigg\} \\
        & = \pr \Big( \overline{R}_{1, s} - \mu_1 \leq s^{-1} \big[ \mu_1 \lambda_2 - \lambda_1 - C_1 \Delta_k (s + \lambda_2)\big]\Big) \\
        (\text{letting }\lambda_2 = 0) & = \pr \Big( \mu_1 - \overline{R}_{1, s} \geq s^{-1} (\lambda_1 + C_1 \Delta_k s)\Big) \\
        & \leq \exp \bigg\{ - \frac{2 (\lambda_1 + C_1 \Delta_k s)^2}{s}\bigg\} \\
        (\text{letting }\lambda_1 = \lambda s) & = \exp \big\{ - 2 s (\lambda + C_1 \Delta_k)^2\big\} \leq T^{-\eta}
    \end{aligned}
\end{equation*}
for any $\eta > 1$ if we take $s \geq s_{a, 2} := \frac{\eta \log T}{2 (\lambda + C_1 \Delta_k)^2}$, and hence we will get
\begin{equation*}
    a_{k, s, 2} \leq T \cdot T^{-\eta} = T^{-\eta + 1}.
\end{equation*}

